mapper.select:
SELECT al.id ,al.stock_code ,al.stock_name ,al.stock_short_name ,al.industry_code ,al.industry_name ,al.latest_rating ,al.previous_rating ,al.adjust_type ,al.adjust_mode ,al.target_pool_id ,p.pool_name target_pool_path ,al.adjust_batch_no ,al.audit_status ,al.adjuster_name ,al.submit_time FROM ip_adjust_log_stock al LEFT JOIN ip_investment_pool p ON p.id = al.target_pool_id AND p.is_deleted = 0 WHERE al.is_deleted = 0
AND al.target_pool_id IN
#{id}
AND al.stock_code LIKE CONCAT('%', #{stockCode}, '%')
AND al.submit_time >= #{adjustTimeStart}
AND al.submit_time < #{adjustTimeEndExclusive}
AND al.industry_code = #{industryCode}
AND al.adjuster_name LIKE CONCAT('%', #{adjusterName}, '%')
AND al.adjust_mode = #{adjustMode}
AND al.audit_status = #{auditStatus}
ORDER BY al.submit_time DESC ,al.adjust_batch_no DESC ,al.id DESC
